let r = materialize(MiniBankLaReadings(7d)
| where $__timeFilter(TimeGenerated) and Item startswith 'Business transactions P95'
| extend x = (TimeGenerated - now()) / 1d);
let s = materialize(r
| summarize n = count(), sx = sum(x), sy = sum(Value), sxx = sum(x * x), sxy = sum(x * Value)
| extend b = (n * sxy - sx * sy) / (n * sxx - sx * sx)
| extend a = (sy - b * sx) / n);
let a = toscalar(s | project a);
let b = toscalar(s | project b);
r
| project TimeGenerated, ['P95 per hour'] = Value, ['Trend (straight line)'] = a + b * x, ['Warning 800 ms'] = 800.0, ['Limit 1000 ms'] = 1000.0
| order by TimeGenerated asc

